import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"线宽压窄与带宽","description":"","frontmatter":{"title":"线宽压窄与带宽","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/laser-linewidth-narrowing.md","filePath":"litho/laser-linewidth-narrowing.md","lastUpdated":1789023840000}'),c={name:"litho/laser-linewidth-narrowing.md"};function m(_,a,E,A,f,B){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="线宽压窄与带宽" tabindex="-1">线宽压窄与带宽 <a class="header-anchor" href="#线宽压窄与带宽" aria-label="Permalink to &quot;线宽压窄与带宽&quot;">​</a></h1><div class="epigraph"><p>准分子的自然线宽对高 NA 物镜太宽。压窄到皮米量级，色差与焦深才进预算；压得过窄，脉冲能量和相干性又会找上门。</p><footer>—— 对照 [色差与光源带宽](/litho/chromatic-bandwidth)；Cymer 等对 narrowing 的公开说明</footer></div><p><a href="/litho/arf-excimer-laser">上一课</a>给出放电光谱。缺口是：这条光谱对 <a href="/litho/chromatic-bandwidth">Zernike 色差</a> 和焦深是否可接受。本课钉线宽压窄，不重做阿贝或瑞利。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高 NA 浸没物镜有残余色散。光源积分带宽 \\(\\Delta\\lambda\\) 过宽，不同波长的焦面错开，等效于焦深被吃、NILS 掉。自由运行准分子的带宽远大于物镜预算，必须腔内光栅或棱镜压窄。压得过窄：提取效率下降、斑纹（<a href="/litho/speckle">speckle</a>）上升，因为时间相干变长。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开手段：腔内扩束 + 光栅选频，反馈锁中心波长。指标用 FWHM 或 E95 积分带宽，单位 pm。监测：波长计进剂量/波长闭环。换胶或换 NA 配方可能换带宽规格，不是「越窄越好」。</p>',7)),(e(),s(p,null,{default:r(()=>[h(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E6%94%BE%E7%94%B5%E5%AE%BD%E5%B8%A6%22%5D%20--%3E%20GR%5B%22%E5%85%89%E6%A0%85%E5%8E%8B%E7%AA%84%22%5D%0A%20%20GR%20--%3E%20BW%5B%22%E7%A7%AF%E5%88%86%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20BW%20--%3E%20CA%5B%22%E8%89%B2%E5%B7%AE%20%2F%20%E7%84%A6%E6%B7%B1%22%5D%0A%20%20BW%20--%3E%20SP%5B%22%E6%96%91%E7%BA%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">中心波长漂移与带宽是两件事。漂移把整场焦面挪走；带宽把焦面涂厚。稳定环两套传感器。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>物镜的纵向色差把 \\(\\Delta\\lambda\\) 映射成 \\(\\Delta z\\)。预算从镜头设计来，光源必须供得上。时间相干长度 \\(\\sim\\lambda^2/\\Delta\\lambda\\)，带宽变窄，照明相干性变长，斑纹对比上升——与 <a href="/litho/temporal-spatial-coherence">时间与空间相干</a> 同一骨架。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课脉冲能量与重复频率：带宽规格约束下还要出功率。不在本课写气体寿命。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>压窄是为色差与焦深，不是为了「光谱好看」。</li><li>过窄付能量与斑纹。用积分带宽进镜头预算。</li><li>出处：色差课；准分子 narrowing 公开技术。</li></ul>',7))])}const D=l(c,[["render",m]]);export{b as __pageData,D as default};
